import * as store from './store.js';
import {freeBeds,haversine,candidates,guidance} from './model.js';
import {renderMap,clearMap} from './map.js';
import {startCamera,stopCamera,capture,readImage,analyzeBrowser} from './camera.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const date=s=>new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
const paths={arrow:'M5 12h14m-5-5 5 5-5 5',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',phone:'M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4c0 2-2 3-4 2C9 19 5 15 3 7 2 5 3 3 5 3Z',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 8 15 8 15S25 10 20 5Z M3 12h5l2-4 3 8 2-4h6',shield:'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7Z m-5 9 3 3 6-6',camera:'M8 5 6 8H3v12h18V8h-3l-2-3Z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',hospital:'M4 21V5h16v16M9 21v-5h6v5M12 7v6M9 10h6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'M5 12l4 4L20 5',plus:'M12 5v14M5 12h14',activity:'M2 12h5l3-8 4 16 3-8h5',box:'M3 7l9-4 9 4v11l-9 4-9-4Z M3 7l9 5 9-5M12 12v10',truck:'M2 6h12v12H2ZM14 10h4l4 4v4h-8M8 18a2 2 0 1 1-4 0m16 0a2 2 0 1 1-4 0',file:'M5 3h9l5 5v13H5ZM14 3v6h5M8 13h8m-8 4h6',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3m0-17a4 4 0 0 1 0 8m3 3c3 0 3 3 3 6',volume:'M3 9h4l5-5v16l-5-5H3Z M16 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14',external:'M14 3h7v7m-1-6L10 14m-1-9H3v16h16v-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.heart}"/></svg>`;
const badge=(label,color='')=>`<span class="badge ${color}">${esc(label)}</span>`;
const statusLabel=s=>({reported:'Reported',requested:'Awaiting acceptance',accepted:'Hospital accepted',en_route:'En route',reroute_pending:'Alternative awaiting acceptance',arrived:'Handover complete',discharged:'Discharged',simulated_paid:'Paid · simulation',simulated_acknowledgement:'Acknowledged · simulation'}[s]||s.replaceAll('_',' '));
const statusBadge=s=>badge(statusLabel(s),['requested','reroute_pending','submitted','requested'].includes(s)?'orange':s==='reported'?'blue':'');
const btn=(label,action,attrs='',kind='')=>`<button class="btn ${kind}" data-do="${action}" ${attrs}>${label}</button>`;
let state,role='patient',page='home',subtab='overview',coords={lat:28.5672,lon:77.2100},locationLabel='Example coordinates · AIIMS area, New Delhi',liveHospitals=[],directoryMeta=null,directoryError='',directoryLoading=false;
let cameraImage=null,cameraResult=null,scene=null,questions={safe:'',responsive:'',breathing:'',bleeding:''},poll=null,busy=false;
let autoRefresh=store.subscribe(()=>refresh());
const hospitalName=id=>state.hospitals.find(h=>h.id===id)?.name||'Not yet accepted';
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6000);}
function modal(title,html,onSubmit){const d=$('#dialog');d.innerHTML=`<button class="close" aria-label="Close dialog" data-do="close">×</button><h2 id="dialog-title">${title}</h2>${html}`;d.showModal();const form=d.querySelector('form');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)));d.close();}catch(e){form.querySelector('.form-error').textContent=e.message;}finally{button.disabled=false;}});}
function formEnd(label='Save'){return `<p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-do="close">Cancel</button><button type="submit" class="btn primary">${label}</button></div></form>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function options(items,selected){return items.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');}
function roleName(r){return {patient:'Patient & family',hospital:'Hospital team',dispatch:'Ambulance dispatch',pharmacy:'Pharmacy & stock',government:'Administration'}[r];}
function shell(content){
  const nav=role==='patient'?[['home','Overview'],['emergency','Emergency help'],['nearby','Nearby hospitals'],['journey','My care journey']]:[['dashboard','Workspace'],['journey','Patient journeys'],['audit','Activity log'],['guide','Demo guide']];
  $('#app').innerHTML=`<header><div class="header-inner"><a class="brand" href="#home" data-nav="home"><img src="/icon.svg" alt="">health<span><em>sos</em></span></a><nav class="topnav" aria-label="Main navigation">${nav.map(([key,label])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav><label class="role-select"><span>Demo workspace</span><select id="role" aria-label="Select demo workspace">${options(['patient','hospital','dispatch','pharmacy','government'].map(r=>[r,roleName(r)]),role)}</select></label></div></header><div class="prototype-bar"><span class="dot"></span><strong>NEEEV PROTOTYPE</strong><span>· ${store.mode()==='sqlite'?'Shared temporary SQLite':'Private browser sandbox'} · No real dispatch or payments</span><span class="right">Made for the moments that matter. <button class="link-button" data-nav="guide">How to try it ${icon('arrow')}</button></span></div><main id="main" tabindex="-1">${content}</main><footer><span><span class="footer-brand">Health SOS.</span> &nbsp; A little less uncertainty. A better next step.</span><span><a href="https://112.gov.in/" target="_blank" rel="noopener">Emergency services: 112</a> &nbsp;·&nbsp; <button class="link-button" data-do="privacy">Privacy & prototype limits</button> &nbsp;·&nbsp; <a href="https://github.com/uniqueenterprisesexport-create/Health-sos" target="_blank" rel="noopener">Source code</a></span></footer>`;
}
const illustration=`<svg class="care-illustration" viewBox="0 0 470 210" role="img" aria-label="Illustration of a caregiver supporting a patient, with a hospital in the background"><path d="M25 187h420" stroke="#c5d5bd" stroke-width="2"/><rect x="284" y="55" width="135" height="132" rx="12" fill="#f9fbf5"/><rect x="326" y="29" width="52" height="53" rx="13" fill="#126b5d"/><path d="M352 41v29m-14-14h28" stroke="#fff" stroke-width="8"/><path d="M302 102h18m19 0h18m19 0h20m-94 23h18m19 0h18m19 0h20" stroke="#c6d8bd" stroke-width="10"/><rect x="338" y="153" width="25" height="34" fill="#dce7d5"/><circle cx="160" cy="52" r="23" fill="#dfac83"/><path d="M138 51c-5-34 47-41 48-2l-9-11-39 13" fill="#213d38"/><path d="m146 76-31 46 23 41 22-12-14-28 19-17 17 43 33-5-21-58Z" fill="#ed7959"/><path d="m141 155 1 32h-30m72-43 17 43h25" stroke="#213d38" stroke-width="17" fill="none" stroke-linecap="round"/><path d="m182 90 27 24 26-22" stroke="#dfac83" stroke-width="13" fill="none" stroke-linecap="round"/><circle cx="240" cy="73" r="20" fill="#c68762"/><path d="M221 71c0-30 45-25 40 5l-11-16Z" fill="#233f38"/><path d="m229 93-18 47 39 15 17-44-18-19" fill="#507d6b"/><path d="m234 148 14 39h25m-48-44-24 44h-21" stroke="#304b41" stroke-width="14" fill="none" stroke-linecap="round"/><path d="m250 104 16 30 17-3" stroke="#c68762" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M76 188v-47m0 24c-31 0-25-37-25-37 27 0 25 37 25 37m0-8c27 0 26-33 26-33-25 0-26 33-26 33" stroke="#8da88b" stroke-width="3" fill="#c8d9bc"/><circle cx="90" cy="47" r="17" fill="#f8fbf3"/><path d="m83 47 5 5 9-10" stroke="#126b5d" stroke-width="3" fill="none"/><path d="M435 148v39m0-13c-17-2-17-25-17-25 18 0 17 25 17 25m0-12c18-3 16-26 16-26-15 1-16 26-16 26" fill="#cad9c0" stroke="#9bb195" stroke-width="2"/></svg>`;
function title(eyebrow,heading,description,actions=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p>${description}</p></div><div class="buttons">${actions}</div></div>`;}
function empty(text,action=''){return `<div class="empty">${icon('heart')}${text}${action?`<div class="buttons mt" style="justify-content:center">${action}</div>`:''}</div>`;}
function home(){
  const latest=state.incidents[0];
  return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Someone to turn to. A way forward.</div><h1>When it matters,<br><span>help starts here.</span></h1><p>Find a nearby hospital, take the next safe step, and keep the people caring for you connected.</p><div class="buttons">${btn(icon('plus')+' I need emergency help','navigate','data-page="emergency"','emergency')}${btn(icon('pin')+' Find a hospital','navigate','data-page="nearby"')}</div><div class="hero-note">${icon('shield')}In immediate danger? Call <a href="tel:112">112</a> first. This prototype does not contact emergency services.</div></div><div class="hero-art"><div class="art-tag"><span class="dot"></span> Care that connects</div>${illustration}<div class="art-foot">${icon('heart')}From the first moment to the right care.<span>NEEEV / 01</span></div></div></section><section><div class="section-heading"><h2>What do you need right now?</h2><p>One step at a time.</p></div><div class="quick-grid">${[['camera','Guided emergency help','Use your camera, answer a few questions, and prepare information for a responder.','emergency'],['hospital','A hospital near me','Search real hospital listings around your location. Check details before travelling.','nearby'],['activity','Follow a care journey','See hospital acknowledgement, transport, and handover in one place.','journey']].map(([i,t,d,p])=>`<button class="quick-card" data-nav="${p}"><span class="quick-icon">${icon(i)}</span>${icon('arrow')}<h3>${t}</h3><p>${d}</p></button>`).join('')}</div></section><section class="grid-2 mt"><div class="card"><div class="card-head"><div><h3>Your care, without the guesswork.</h3><p>A clear handover at every step.</p></div>${badge('CONNECTED CARE','outline')}</div><div class="steps"><div class="step"><span>01</span><b>Ask for help</b>Share the location and what you can observe.</div><div class="step"><span>02</span><b>Get acknowledged</b>A hospital team accepts the incoming patient.</div><div class="step"><span>03</span><b>Stay connected</b>Follow the journey through transport and handover.</div></div></div><div class="card pale"><div class="card-head"><div><h3>${latest?'Your latest demo journey':'A calm place to start.'}</h3><p>${latest?esc(latest.id):'Try the full experience, without making a real emergency request.'}</p></div>${icon(latest?'activity':'users')}</div>${latest?`<div class="row"><div class="row-main"><strong>${esc(latest.name)}</strong><p>${esc(hospitalName(latest.hospitalId))}</p></div>${statusBadge(latest.status)}</div>${btn('Open care journey '+icon('arrow'),'navigate','data-page="journey"','soft sm')}`:`<p>Explore a fictional accident scenario and move between the patient, hospital, and ambulance workspaces.</p>${btn('Start a sample journey '+icon('arrow'),'sample','','soft')}`}</div></section><div class="trust-strip"><span>${icon('shield')} Your camera stays off until you choose</span><span>${icon('pin')} Real nearby listings · unverified availability</span><span>${icon('users')} Designed around patients and families</span><span>${icon('file')} Every demo action has a record</span></div>`;
}
function emergency(){
  const g=guidance(questions);
  return title('First, the next safe step','You don’t have to figure it out alone.','Call emergency services first. Camera processing checks image quality; it cannot diagnose injuries.',`<a class="btn emergency" href="tel:112">${icon('phone')} Call 112</a>`)+`<div class="notice red"><strong>Prototype only.</strong> Guidance is a limited reference flow, pending clinician review. Do not delay an emergency call to photograph someone or use this app.</div><div class="grid-2 grid-even"><section class="card"><div class="card-head"><div><h3>A clearer picture for a responder</h3><p>OpenCV image-quality analysis · no injury diagnosis</p></div>${badge('CAMERA OPTIONAL','outline')}</div><div class="camera-stage" id="camera-stage">${cameraImage?`<img src="${cameraImage}" alt="Your selected scene, processed only when you choose">`:`<div class="camera-empty">${icon('camera')}<p>Your camera is off.</p><p class="tiny">You choose what to share. Images are not saved.</p></div>`}</div><div class="camera-controls">${btn(icon('camera')+' Open camera','camera-start')}${btn('Upload image','camera-upload')}${cameraImage?btn('Clear image','camera-clear','','sm'):btn('Try sample image','camera-sample','','sm')}</div><input class="visually-hidden" id="image-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Upload image"><div id="camera-actions" class="buttons mt">${cameraImage?btn('Check image with OpenCV','camera-analyze','','primary'):''}</div><div id="camera-result">${cameraMetrics()}</div><details><summary>Processing options & optional AI</summary>${cameraImage?btn('Test browser OpenCV engine','camera-browser','','sm'):''}<p class="small muted">Requires a vision-capable OpenRouter model configured on the server. This sends the selected image to that provider. It describes visible details; it does not choose medical treatment.</p><label class="check"><input type="checkbox" id="ai-consent"> I have permission to share this image with the configured AI provider.</label>${btn('Describe visible scene','camera-ai','','sm')}<p id="scene-description" class="small">${scene?esc(scene):''}</p></details></section><section class="card"><div class="card-head"><div><h3>Tell us what you can observe</h3><p>Your answers select a fixed reference flow.</p></div>${icon('heart')}</div><form id="questions"><div class="form-grid">${[['safe','Is the scene safe?',[['yes','Yes'],['no','No / unsure']]],['responsive','Does the person respond?',[['yes','Yes'],['no','No / unsure']]],['breathing','Does breathing appear normal?',[['yes','Yes'],['no','No'],['unsure','I cannot tell']]],['bleeding','Heavy external bleeding visible?',[['no','No / unsure'],['yes','Yes']]]].map(([key,label,opts])=>`<label class="field">${label}<select name="${key}">${options([['','Not answered'],...opts],questions[key])}</select></label>`).join('')}</div></form><div class="notice mt">A camera cannot confirm consciousness, normal breathing, or internal injuries. Tell the emergency dispatcher what you observe.</div><h3 id="guidance-title">${g.title}</h3><ol class="protocol" id="guidance-steps">${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="buttons">${btn(icon('volume')+' Read aloud','speak','','soft sm')}${btn('Create demo incident '+icon('arrow'),'new-incident','','primary sm')}</div><details><summary>Reference & limitations</summary><p class="small muted">General reference: <a href="https://www.redcross.org/take-a-class/first-aid/performing-first-aid/first-aid-steps" target="_blank" rel="noopener">American Red Cross first-aid steps</a>. These sample flows are not a clinically approved service. A qualified team must review protocols, translations, accessibility, and intended use before deployment.</p></details></section></div>`;
}
function cameraMetrics(){if(!cameraResult)return `<p class="small muted">Analysis starts only when you choose. Images remain in memory and are cleared when you leave this screen.</p>`;const r=cameraResult;return `<div class="metric-grid"><div class="metric">Lighting<strong>${r.brightness}/255</strong>Mean brightness</div><div class="metric">Image detail<strong>${r.sharpness}</strong>Laplacian variance</div><div class="metric">Resolution<strong>${r.width} × ${r.height}</strong>Pixels</div></div><p class="small muted">${esc(r.engine)}</p>${r.warnings.length?`<div class="notice">${r.warnings.map(esc).join('<br>')}</div>`:`<div class="notice green">No image-quality warnings at these heuristic thresholds. This says nothing about the patient’s condition.</div>`}`;}
function nearby(){
  const sorted=[...liveHospitals].map(h=>({...h,distance:haversine(coords,h)})).sort((a,b)=>a.distance-b.distance);
  const bbox=[coords.lon-.035,coords.lat-.025,coords.lon+.035,coords.lat+.025].map(n=>n.toFixed(6)).join(',');
  return title('Find your next point of care','Real hospitals. Around you.','Search OpenStreetMap listings using your location or enter coordinates. Directory presence does not confirm emergency capability or beds.')+`<section class="card"><div class="card-head"><div><h3>${icon('pin')} Search your area</h3><p id="location-label">${esc(locationLabel)}</p></div>${badge('LIVE DIRECTORY','blue')}</div><form id="location-form" class="location-controls">${field('Latitude','lat',coords.lat,'number','step="any" min="-90" max="90" required')}${field('Longitude','lon',coords.lon,'number','step="any" min="-180" max="180" required')}<label class="field">Radius<select name="radius"><option value="3000">3 km</option><option value="8000" selected>8 km</option><option value="15000">15 km</option></select></label><button class="btn primary" type="submit" ${directoryLoading?'disabled':''}>${directoryLoading?'Searching…':'Search hospitals'}</button>${btn(icon('pin')+' Use my location','locate')}</form><div class="notice">Real listings are shown below. <strong>Call to confirm services and availability.</strong> Bookings and capacity commitments are available only for explicitly fictional hospitals in the demo workspaces.</div>${directoryError?`<div class="notice red" role="alert">${esc(directoryError)} <a href="https://www.google.com/maps/search/hospitals/@${coords.lat},${coords.lon},14z" target="_blank" rel="noopener">Open hospital map search</a></div>`:''}<div class="grid-2 grid-even"><div class="map-panel"><div id="hospital-map" role="region" aria-label="Map of your search location and returned hospital listings"></div></div><div class="hospital-list">${directoryLoading?empty('Looking up real hospital listings…'):sorted.length?sorted.map(h=>`<article class="row"><div class="row-icon">${icon('hospital')}</div><div class="row-main"><strong>${esc(h.name)}</strong><p>${esc(h.address||'Address not provided in directory')}</p><div class="buttons" style="margin-top:9px"><a class="btn sm" href="https://www.google.com/maps/dir/?api=1&destination=${h.lat},${h.lon}" target="_blank" rel="noopener">Directions ${icon('external')}</a><a class="btn sm" href="${h.osm}" target="_blank" rel="noopener">Source listing</a>${h.phone?`<a class="btn sm" href="tel:${esc(h.phone.replace(/[^+\d,;]/g,''))}">Call listing</a>`:''}</div></div><div><div class="hospital-distance">${h.distance.toFixed(1)} km</div><div class="tiny muted">straight-line</div></div></article>`).join(''):empty(directoryMeta?'No named hospitals returned in this radius. Try a wider search.':'Use your location or search the example coordinates to see real hospitals.')}</div></div>${directoryMeta?`<p class="tiny muted">${esc(directoryMeta.source)} · Retrieved ${date(directoryMeta.at)} · © OpenStreetMap contributors · Not a live bed feed.</p>`:''}</section>`;
}
function incidentCard(i,controls=false){
  const h=state.hospitals.find(h=>h.id===i.hospitalId),pending=state.hospitals.find(h=>h.id===i.proposedHospitalId);let actions='';
  if(controls){
    if(role==='patient')actions+=btn('Prepare family update','family',`data-id="${i.id}"`,'sm');
    if(['reported','requested'].includes(i.status)&&['patient','dispatch','hospital'].includes(role))actions+=btn('Request hospital','request-hospital',`data-id="${i.id}"`,'sm');
    if(['requested','reroute_pending'].includes(i.status)&&role==='hospital')actions+=btn('Accept patient','accept',`data-id="${i.id}"`,'primary sm')+btn('Decline request','decline',`data-id="${i.id}"`,'sm');
    if(['accepted','en_route'].includes(i.status)&&['hospital','dispatch'].includes(role))actions+=btn('Propose reroute','reroute',`data-id="${i.id}"`,'sm');
    if(['accepted','en_route'].includes(i.status)&&role==='hospital')actions+=btn('Receive handover','arrive',`data-id="${i.id}"`,'primary sm');
    if(i.status==='arrived'&&role==='hospital')actions+=btn('Create claim','claim',`data-id="${i.id}"`,'sm')+btn('Discharge','discharge',`data-id="${i.id}"`,'sm');
    if(!i.ambulanceId&&['reported','requested','accepted'].includes(i.status)&&role==='dispatch')actions+=btn('Assign ambulance','assign',`data-id="${i.id}"`,'primary sm');
    if(['patient','hospital','dispatch'].includes(role)&&!state.reports.some(r=>r.incidentId===i.id))actions+=btn('Draft incident report','report',`data-id="${i.id}"`,'sm');
  }
  const stage=['reported','requested','accepted','en_route','arrived'],idx=stage.indexOf(i.status);
  return `<article class="card"><div class="card-head"><div><h3>${esc(i.name)}</h3><p>${esc(i.id)} · ${date(i.createdAt)}</p></div>${statusBadge(i.status)}</div><p class="small">${esc(i.notes||'No additional observations entered.')}</p><div class="row"><div class="row-icon">${icon('hospital')}</div><div class="row-main"><strong>${h?esc(h.name):'Awaiting receiving hospital'}</strong><p>${pending?`Pending request: ${esc(pending.name)}`:'Clinical need: '+esc(i.need)+' · entered by user / staff'}</p></div>${i.ambulanceId?badge(i.ambulanceId,'blue'):''}</div><div class="progress-line">${stage.map((s,n)=>`<span class="${n<=idx||i.status==='discharged'?'done':''}">${statusLabel(s)}</span>`).join('')}</div>${actions?`<div class="buttons mt">${actions}</div>`:''}<details><summary>View handover timeline</summary><ol class="timeline">${i.events.map(e=>`<li><time>${date(e.at)}</time>${esc(e.text)}</li>`).join('')}</ol></details></article>`;
}
function journey(){return title('A clear handover, every time','Your care journey','A shared incident reference keeps the patient, dispatcher, and receiving team connected.',btn('Request OPD slot','appointment','','')+btn('New demo incident','new-incident','','primary'))+`<div class="notice green">These are prototype incidents. Acknowledgements, transport and hospital capacity are simulated. No real hospital is notified.</div><div class="stack">${state.incidents.length?state.incidents.map(i=>incidentCard(i,true)).join(''):empty('No journeys yet. Start with a fictional incident to explore the complete handover.',btn('Start sample journey','sample','','primary'))}</div>`;}
function stats(items){return `<div class="stat-grid">${items.map(([n,t,note])=>`<div class="card stat"><div class="number">${n}</div><div class="small">${t}</div>${note?`<div class="tiny muted">${note}</div>`:''}</div>`).join('')}</div>`;}
function hospital(){
  return title('Hospital operations · fictional facilities','Be ready before they arrive.','Manage incoming requests, staffed capacity, walk-in arrivals, and accountable handovers.',btn('Add walk-in','walkin','','primary'))+stats([[state.incidents.filter(i=>['requested','reroute_pending'].includes(i.status)).length,'Awaiting acceptance'],[state.incidents.filter(i=>['accepted','en_route'].includes(i.status)).length,'Accepted incoming'],[state.hospitals.reduce((n,h)=>n+freeBeds(state,h),0),'Uncommitted demo beds'],[state.incidents.filter(i=>i.status==='arrived').length,'Active demo admissions']])+`<div class="quick-grid">${state.hospitals.map(h=>{const held=state.incidents.filter(i=>i.hospitalId===h.id&&['accepted','en_route','reroute_pending'].includes(i.status)).length;return `<article class="card"><div class="card-head"><h3>${esc(h.name)}</h3>${badge('DEMO','outline')}</div><p class="tiny muted">${h.capabilities.join(' · ')}</p><div class="capacity" aria-label="${h.occupied} occupied, ${held} held">${Array.from({length:h.beds},(_,n)=>`<i class="${n<h.occupied?'used':n<h.occupied+held?'held':''}"></i>`).join('')}</div><p class="small">${h.occupied} occupied · ${held} commitments · <strong>${freeBeds(state,h)} free</strong></p>${h.occupied+held>h.beds?`<div class="notice red">Capacity conflict. Review incoming commitments with clinical staff.</div>`:''}<p class="tiny muted">Updated ${date(h.updatedAt)}</p>${btn('Update capacity','capacity',`data-id="${h.id}"`,'sm')}</article>`;}).join('')}</div><div class="section-heading"><h2>Incoming & current patients</h2><p>Staff acknowledgement required</p></div><div class="stack">${state.incidents.length?state.incidents.map(i=>incidentCard(i,true)).join(''):empty('No incoming patients. Create a sample incident in the patient workspace.',btn('Create sample','sample','','primary'))}</div>`;
}
function dispatch(){return title('Ambulance coordination · simulation','Every handover has an owner.','Assign transport, track accepted destinations, and escalate capacity changes. No real ambulance is contacted.')+stats([[state.ambulances.filter(a=>a.status==='available').length,'Units available'],[state.ambulances.filter(a=>a.status!=='available').length,'Units assigned'],[state.incidents.filter(i=>i.status==='reroute_pending').length,'Reroutes pending'],[state.incidents.filter(i=>i.status==='reported').length,'Unassigned reports']])+`<section class="card"><div class="card-head"><h3>Transport units</h3>${badge('FICTIONAL FLEET','outline')}</div>${state.ambulances.map(a=>`<div class="row"><div class="row-icon">${icon('truck')}</div><div class="row-main"><strong>${esc(a.label)}</strong><p>${a.incidentId?esc(a.incidentId):'Ready for a demo assignment'}</p></div>${statusBadge(a.status)}</div>`).join('')}</section><div class="section-heading"><h2>Incident coordination</h2></div><div class="stack">${state.incidents.length?state.incidents.map(i=>incidentCard(i,true)).join(''):empty('No incidents to coordinate yet.',btn('Create sample','sample','','primary'))}</div>`;}
function pharmacy(){
  const today=new Date().toISOString().slice(0,10),active=state.medicines.filter(m=>m.status==='active'&&m.expiry>=today);
  return title('Pharmacy & inventory · demonstration stock','The right stock. Ready when needed.','Batch-level stock, expiry quarantine, approved replenishment, and documented collection.',btn('Run stock & expiry check','stock-scan','','primary'))+stats([[active.reduce((n,m)=>n+m.quantity,0),'Active stock units'],[active.filter(m=>m.quantity<m.min).length,'Batches below minimum'],[state.medicines.filter(m=>m.status==='quarantined').length,'Quarantined batches'],[state.orders.filter(o=>o.status!=='received').length,'Open supply requests']])+`<section class="card"><div class="card-head"><div><h3>Medicine & supply batches</h3><p>Fictional stock · no prescribing or substitution advice</p></div>${badge('BATCH TRACKING')}</div><div class="table-wrap"><table><thead><tr><th>Item / batch</th><th>Units</th><th>Expiry</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.medicines.map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${esc(m.batch)}</small></td><td>${m.quantity}<small>Minimum ${m.min}</small></td><td>${esc(m.expiry)}</td><td>${badge(m.expiry<today&&m.status==='active'?'expired':m.status,m.status==='quarantined'?'red':'')}</td><td>${m.status==='active'&&m.expiry>=today?btn('Dispense','dispense',`data-id="${m.id}"`,'sm'):'<span class="tiny muted">Dispensing blocked</span>'}</td></tr>`).join('')}</tbody></table></div></section><div class="grid-2 grid-even mt"><section class="card"><h3>Replenishment requests</h3><p class="small muted">Requests go to a simulated supplier administration queue.</p>${state.orders.length?state.orders.map(o=>`<div class="row"><div class="row-main"><strong>${esc(state.medicines.find(m=>m.id===o.medicineId)?.name)}</strong><p>${esc(o.id)} · ${o.quantity} units</p></div>${statusBadge(o.status)}${o.status==='approved'?btn('Receive new batch','receive',`data-id="${o.id}"`,'sm'):''}</div>`).join(''):empty('Run the stock check to create low-stock requests.')}</section><section class="card"><h3>Expired stock collections</h3><p class="small muted">Quarantine → authorised collection → certificate. No physical collection is arranged.</p>${state.collections.length?state.collections.map(c=>`<div class="row"><div class="row-main"><strong>${esc(c.id)}</strong><p>${c.quantity} units · ${esc(c.certificate||'Awaiting simulated collection')}</p></div>${statusBadge(c.status)}</div>`).join(''):empty('Expiry checks create collection requests for quarantined batches.')}</section></div>`;
}
function government(){
  const current=state.tariffs.filter(t=>!state.tariffs.some(n=>n.code===t.code&&n.state===t.state&&n.scheme===t.scheme&&n.version>t.version));
  const tabs=[['overview','Overview'],['tariffs','Tariffs & claims'],['supply','Supply & collection'],['reports','Incident notifications']];
  let content='';
  if(subtab==='overview')content=stats([[state.claims.filter(c=>c.status==='submitted').length,'Claims for review'],[state.orders.filter(o=>o.status==='requested').length,'Supply requests'],[state.reports.filter(r=>r.status==='draft').length,'Draft notifications'],[money(state.settlements.reduce((n,b)=>n+b.amount,0)),'Simulated settlements']])+`<div class="grid-2 grid-even"><section class="card pale"><h3>An accountable prototype.</h3><p>This dashboard represents a participating scheme administrator. All tariffs are fictional agreement rates; they are not official government prices.</p><p>Government integration, price enforcement, procurement, and funded payments need authorised partnerships.</p>${btn('Review tariffs & claims','subtab','data-tab="tariffs"','soft')}</section><section class="card"><h3>Sandbox controls</h3><p>Export a demonstration record or reset all incidents, stock requests and payments. This sandbox is not for real patient data.</p><div class="buttons">${btn('Export audit JSON','export','','sm')}${btn('Reset sandbox','reset','','danger sm')}</div></section></div><div class="section-heading"><h2>Recent activity</h2></div>${auditTable(state.audit.slice(0,8))}`;
  if(subtab==='tariffs')content=`<div class="grid-2 grid-even"><section class="card"><div class="card-head"><div><h3>Current agreement tariffs</h3><p>Versioned demonstration rates · INR</p></div>${btn('Add / revise','tariff','','sm')}</div>${current.map(t=>`<div class="row"><div class="row-main"><strong>${esc(t.name)}</strong><p>${esc(t.code)} · ${esc(t.state)} · v${t.version}<br>${esc(t.scheme)}</p></div><strong>${money(t.amount)}</strong></div>`).join('')}</section><section class="card"><div class="card-head"><div><h3>Weekly settlement simulator</h3><p>Only approved claims enter a batch.</p></div></div><p>Approved balance: <strong>${money(state.claims.filter(c=>c.status==='approved').reduce((n,c)=>n+c.amount,0))}</strong></p>${btn('Run weekly settlement','settle','','primary sm')}<p class="tiny muted">Manual trigger for demonstration. No bank transfers, funds, or scheduled payout service.</p>${state.settlements.map(b=>`<div class="row"><div class="row-main"><strong>${esc(b.id)}</strong><p>${date(b.createdAt)} · ${b.claimIds.length} claims<br>${b.transfers.map(t=>`${esc(hospitalName(t.hospitalId))}: ${money(t.amount)}`).join('<br>')}</p></div>${money(b.amount)}</div>`).join('')}</section></div><section class="card mt"><h3>Claims review</h3>${state.claims.length?`<div class="table-wrap"><table><thead><tr><th>Claim / incident</th><th>Tariff snapshot</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.claims.map(c=>`<tr><td>${esc(c.id)}<small>${esc(c.incidentId)} · ${esc(hospitalName(c.hospitalId))}</small></td><td>${esc(c.tariff.name)}<small>v${c.tariff.version} · ${esc(c.tariff.scheme)}</small></td><td>${money(c.amount)}</td><td>${statusBadge(c.status)}</td><td>${c.status==='submitted'?btn('Approve','approve-claim',`data-id="${c.id}"`,'sm'):''}</td></tr>`).join('')}</tbody></table></div>`:empty('Hospital teams can create a claim after recording patient arrival.')}</section>`;
  if(subtab==='supply')content=`<div class="notice">Government supplier and disposal activities are simulated. Replacement depends on procurement terms; no free replacement is implied.</div><div class="grid-2 grid-even"><section class="card"><h3>Supplier approval queue</h3>${state.orders.length?state.orders.map(o=>`<div class="row"><div class="row-main"><strong>${esc(state.medicines.find(m=>m.id===o.medicineId)?.name)}</strong><p>${esc(o.id)} · ${o.quantity} units</p></div>${statusBadge(o.status)}${o.status==='requested'?btn('Approve supply','approve-order',`data-id="${o.id}"`,'primary sm'):''}</div>`).join(''):empty('Run a stock check in the pharmacy workspace to generate requests.')}</section><section class="card"><h3>Authorised collection queue</h3>${state.collections.length?state.collections.map(c=>`<div class="row"><div class="row-main"><strong>${esc(c.id)}</strong><p>${c.quantity} units · ${esc(c.certificate||'No certificate yet')}</p></div>${statusBadge(c.status)}${c.status!=='disposed'?btn('Record disposal','dispose',`data-id="${c.id}"`,'sm'):''}</div>`).join(''):empty('No collection requests yet.')}</section></div>`;
  if(subtab==='reports')content=`<div class="notice">This simulator does not submit anything to the police. An incident notification is not an FIR. Bystander identity is not required.</div><div class="stack">${state.reports.length?state.reports.map(r=>`<article class="card"><div class="card-head"><h3>${esc(r.id)}</h3>${statusBadge(r.status)}</div><p>${esc(r.summary)}</p><p class="small muted">${esc(r.incidentId)} · ${date(r.createdAt)}${r.officialReference?'<br>Simulator reference: '+esc(r.officialReference):''}</p>${r.status==='draft'?btn('Simulate acknowledgement','ack-report',`data-id="${r.id}"`,'primary sm'):''}</article>`).join(''):empty('Draft an incident notification from a patient journey.')}</div>`;
  return title('Administration · simulated authority','See the system. Keep it accountable.','Manage agreement rates, supply requests, incident notifications, and auditable claim settlement.')+`<div class="tabs" role="group" aria-label="Administration sections">${tabs.map(([key,label])=>`<button data-do="subtab" data-tab="${key}" class="${subtab===key?'active':''}">${label}</button>`).join('')}</div>${content}`;
}
function auditTable(events){return `<section class="card"><div class="table-wrap"><table><thead><tr><th>When</th><th>Workspace</th><th>Action</th><th>Reference / detail</th></tr></thead><tbody>${events.map(e=>`<tr><td class="tiny">${date(e.at)}</td><td>${esc(e.role)}</td><td class="audit-action">${esc(e.action)}</td><td class="small">${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function guide(){return title('Your runnable demonstration','One scenario. Every part connected.','Use fictional patients only. Switch workspaces in the top-right menu; each workspace shares the same sandbox.')+`<div class="notice green">${store.mode()==='sqlite'?'SQLite mode: the local server shares data between browsers.':'Browser mode: temporary IndexedDB data is shared between tabs on this browser and origin, not between different devices.'} Demo roles are freely selectable and are not production identity verification.</div><div class="help-grid">${[['01 · Patient & family','Report & request','Start a sample incident, request one of the fictional hospitals, and optionally draft an incident notification. Real nearby hospital names are in the separate live directory.'],['02 · Hospital & dispatch','Accept & transport','Hospital: accept the request. Dispatch: assign an available ambulance. Hospital: receive the handover and create an agreement-based claim.'],['03 · Pharmacy & administration','Complete the loop','Pharmacy: run a stock check. Administration: approve replenishment and record disposal; approve a claim and run a simulated weekly settlement.']].map(([n,t,d])=>`<section class="card"><div class="eyebrow">${n}</div><h3 class="mt">${t}</h3><p>${d}</p></section>`).join('')}</div><section class="card mt"><h3>Try the difficult cases, too.</h3><div class="steps"><div class="step"><span>A</span><b>Capacity changes</b>Record walk-ins or reduce staffed capacity. Propose a reroute; verify the current destination stays until the alternative accepts.</div><div class="step"><span>B</span><b>Expired medicine</b>Attempt a quarantined batch dispense through the API. It is rejected. Receive replenishment into a new batch.</div><div class="step"><span>C</span><b>Live camera & directory</b>Upload an image and run OpenCV. Search your coordinates for real hospital listings. Neither implies clinical clearance or a real booking.</div></div><div class="buttons mt">${btn('Start sample incident','sample','','primary')}${btn('Try nearby hospitals','navigate','data-page="nearby"')}${btn('Try camera processing','navigate','data-page="emergency"')}</div></section><section class="card mt"><h3>What is live, and what is simulated?</h3><div class="table-wrap"><table><thead><tr><th>Working feature</th><th>Boundary</th></tr></thead><tbody><tr><td>Camera / upload → actual OpenCV processing</td><td>Image quality only; no visual injury diagnosis</td></tr><tr><td>Real OpenStreetMap hospital names and coordinates</td><td>No confirmed capability, beds, or hospital notification</td></tr><tr><td>Capacity, acceptance, rerouting, handover</td><td>Fictional participating facilities</td></tr><tr><td>Stock, quarantine, procurement and disposal records</td><td>No physical supply or disposal arranged</td></tr><tr><td>Tariffs, claims and settlement ledger</td><td>Fictional prices; no money moves</td></tr><tr><td>Incident reports and acknowledgement simulator</td><td>No police report or FIR filed</td></tr><tr><td>Optional OpenRouter image description</td><td>Requires server-side credentials and explicit consent</td></tr></tbody></table></div></section>`;}
function render(){clearMap();let content;if(page==='home')content=home();else if(page==='emergency')content=emergency();else if(page==='nearby')content=nearby();else if(page==='journey')content=journey();else if(page==='guide')content=guide();else if(page==='audit')content=title('An accountable care journey','Activity log','Each successful action records its role, timestamp and reference.')+auditTable(state.audit);else content=({hospital,dispatch,pharmacy,government}[role]||home)();if((page==='journey'||(page==='dashboard'&&role==='hospital'))&&state.appointments.length)content+=appointmentList();shell(content);if(page==='nearby')renderMap(coords,liveHospitals);}
async function refresh(){if(busy||$('#dialog')?.open||page==='emergency'||document.activeElement?.matches('input,select,textarea'))return;try{const next=await store.read();if(next.revision!==state.revision){state=next;render();}}catch{}}
function navigate(next){if(page==='emergency'&&next!=='emergency'){stopCamera();cameraImage=null;cameraResult=null;scene=null;if('speechSynthesis'in window)speechSynthesis.cancel();}page=next;history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'instant'});}
async function mutate(action,payload,message='Demo updated.'){const out=await store.act(action,payload,role);state=out.state;render();toast(message);return out.result;}
function newIncident(sample=false){modal(sample?'Start a sample journey':'Create a demo incident',`<p>Simulation only. This does not call emergency services. You can leave the patient unidentified; do not enter real personal information.</p><form><div class="form-grid">${field('Patient label (optional)','name',sample?'Sample patient — road accident':'')}${field('Latitude','lat',coords.lat,'number','step="any" min="-90" max="90" required')}${field('Longitude','lon',coords.lon,'number','step="any" min="-180" max="180" required')}<label class="field">Staff-entered capability request<select name="need">${options([['Emergency','Emergency assessment'],['Trauma','Trauma team'],['CT','CT capability'],['ICU','ICU capability']],'Emergency')}</select></label><label class="field full">Reported observations<textarea name="notes" maxlength="1500">${sample?'Fictional road accident. Condition requires assessment by emergency staff.':''}</textarea></label><label class="check full"><input type="checkbox" name="autoRequest" checked> Automatically request the nearest matching fictional demo hospital. Staff must accept.</label><label class="check full"><input type="checkbox" name="consent"> I have permission to share the entered observations within this prototype.</label></div>${formEnd('Create demo incident')}`,async p=>{if(p.notes.trim()&&!p.consent)throw Error('Confirm permission to share observations, or leave that field blank.');await mutate('incident.create',{...p,autoRequest:!!p.autoRequest,consent:!!p.consent,observations:cameraResult?{engine:cameraResult.engine,qualityOnly:true}:null},'Demo incident created. No real services contacted.');navigate('journey');});}
async function searchHospitals(lat,lon,radius){
  if(!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180)return toast('Enter valid latitude and longitude.',true);
  coords={lat,lon};directoryLoading=true;directoryError='';liveHospitals=[];directoryMeta=null;render();try{const data=await store.nearby(lat,lon,radius);liveHospitals=data.hospitals;directoryMeta=data;toast(`${data.hospitals.length} real hospital listings found.`);}catch(e){directoryError=e.message;toast(e.message,true);}finally{directoryLoading=false;if(page==='nearby')render();}
}
async function locate(){if(!navigator.geolocation)throw Error('Location is unavailable. Enter coordinates manually.');toast('Your browser will ask permission to use your location.');const position=await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(ok,no,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));coords={lat:position.coords.latitude,lon:position.coords.longitude};locationLabel=`Your location · accuracy approximately ${Math.round(position.coords.accuracy)} m`;await searchHospitals(coords.lat,coords.lon,8000);}
function appointmentList(){return `<section class="card mt"><div class="card-head"><h3>Outpatient appointment requests</h3>${badge('DEMO SCHEDULING','outline')}</div>${state.appointments.map(a=>`<div class="row"><div class="row-icon">${icon('clock')}</div><div class="row-main"><strong>${esc(a.name)} · ${esc(a.department)}</strong><p>${esc(hospitalName(a.hospitalId))} · ${date(a.when)}</p></div>${statusBadge(a.status)}${role==='hospital'&&a.status==='requested'?btn('Confirm slot','confirm-appointment',`data-id="${a.id}"`,'sm'):''}</div>`).join('')}</section>`;}
async function doAction(action,el){const id=el.dataset.id;
  switch(action){
    case 'close':$('#dialog').close();break;
    case 'navigate':navigate(el.dataset.page);break;
    case 'subtab':subtab=el.dataset.tab;render();break;
    case 'appointment':modal('Request a demo OPD appointment',`<p>For non-emergency scheduling only. All listed facilities and slots are fictional. Staff confirmation is required.</p><form><div class="form-grid">${field('Patient label','name','Demo patient','text','required')}<label class="field">Hospital<select name="hospitalId">${options(state.hospitals.map(h=>[h.id,h.name]))}</select></label>${field('Department','department','General consultation','text','required')}${field('Requested time','when','','datetime-local','required')}</div>${formEnd('Request demo appointment')}`,async p=>{await mutate('appointment.create',p);navigate('journey');});break;
    case 'confirm-appointment':await mutate('appointment.confirm',{id},'Demo OPD slot confirmed.');break;
    case 'decline':await mutate('hospital.decline',{id},'Proposed request declined; existing destination retained where present.');break;
    case 'family':modal('Prepare a family update',`<p>This creates a message for you to copy and send yourself. No message is sent automatically.</p><form><label class="check"><input name="consent" type="checkbox" required>I have permission to prepare this patient update.</label>${formEnd('Prepare update')}`,async p=>{const text=await mutate('family.share',{id,consent:!!p.consent},'Family update prepared; nothing sent.');setTimeout(()=>modal('Family update — ready to copy',`<label class="field">Select and copy this message<textarea rows="5" readonly>${esc(text)}</textarea></label><p>Share only with someone authorised to receive this information.</p>`),0);});break;
    case 'sample':newIncident(true);break;
    case 'new-incident':newIncident();break;
    case 'locate':await locate();break;
    case 'request-hospital':{const i=state.incidents.find(i=>i.id===id),hs=state.hospitals.filter(h=>h.capabilities.includes(i.need)&&freeBeds(state,h,i.id)>0).sort((a,b)=>haversine(i,a)-haversine(i,b));if(!hs.length)throw Error('No demo hospital has matching free capacity. Ask hospital staff to review.');modal('Request a receiving hospital',`<p>These are fictional participating facilities. A request is not a booking until hospital staff accept.</p><form><label class="field">Receiving hospital<select name="hospitalId">${options(hs.map(h=>[h.id,`${h.name} · ${freeBeds(state,h,i.id)} free demo beds`]))}</select></label>${formEnd('Send demo request')}`,p=>mutate('incident.request',{id,...p},'Request recorded. Switch to Hospital team to accept.'));break;}
    case 'accept':await mutate('hospital.accept',{id},'Hospital staff acceptance recorded in simulation.');break;
    case 'capacity':{const h=state.hospitals.find(h=>h.id===id);modal('Update staffed capacity',`<p>Record actual staffed capacity in the demo. Reduced capacity can conflict with accepted incoming patients; review those journeys.</p><form><div class="form-grid">${field('Staffed beds','beds',h.beds,'number','min="0" max="1000" required')}${field('Occupied beds','occupied',h.occupied,'number','min="0" max="1000" required')}</div>${formEnd('Update capacity')}`,p=>mutate('hospital.capacity',{hospitalId:id,...p}));break;}
    case 'walkin':modal('Record a walk-in arrival',`<p>A walk-in uses the same capacity ledger as incoming patients. Clinical staff determine priority.</p><form><label class="field">Hospital<select name="hospitalId">${options(state.hospitals.map(h=>[h.id,h.name]))}</select></label>${formEnd('Record arrival')}`,p=>mutate('hospital.walkin',p,'Walk-in recorded. Review any capacity conflicts.'));break;
    case 'reroute':{const i=state.incidents.find(i=>i.id===id),hs=candidates(state,i);if(!hs.length)throw Error('No suitable alternative. Current destination retained; escalate to dispatcher.');modal('Propose a confirmed alternative',`<p>The nearest suitable demo hospital is suggested. The current destination remains until the receiving team accepts. Clinical and transport staff must approve any real transfer.</p><form><label class="field">Suggested alternative<select name="hospitalId">${options(hs.map(h=>[h.id,`${h.name} · ${h.distance.toFixed(1)} km straight-line`]))}</select></label>${formEnd('Request alternative')}`,p=>mutate('incident.reroute',{id,...p},'Alternative proposed. Awaiting receiving staff acceptance.'));break;}
    case 'assign':{const available=state.ambulances.filter(a=>a.status==='available');if(!available.length)throw Error('No available demo units.');modal('Assign transport',`<p>Simulation only. No real ambulance is dispatched.</p><form><label class="field">Available unit<select name="ambulanceId">${options(available.map(a=>[a.id,a.label]))}</select></label>${formEnd('Assign demo unit')}`,p=>mutate('dispatch.assign',{id,...p}));break;}
    case 'arrive':modal('Receive the patient handover',`<p>Confirm reception by responsible staff. The ambulance becomes available and the capacity hold becomes an occupied bed.</p><form>${field('Receiving staff label','receivedBy','Demo nurse','text','required maxlength="80"')}${formEnd('Confirm handover')}`,p=>mutate('incident.arrive',{id,...p}));break;
    case 'discharge':await mutate('incident.discharge',{id},'Demo discharge recorded; occupied capacity released.');break;
    case 'report':{const i=state.incidents.find(i=>i.id===id);modal('Draft an incident notification',`<p>No FIR is filed. No police or emergency authority is contacted. Bystander identity is not required.</p><form><label class="field">Unverified incident summary<textarea name="summary" required maxlength="1500">${esc(i.notes||'Accident notification; circumstances require verification.')}</textarea></label>${formEnd('Save draft')}`,p=>mutate('report.create',{id,...p}));break;}
    case 'ack-report':await mutate('report.submit',{id},'Simulator acknowledged the draft. Nothing sent to police.');break;
    case 'stock-scan':await mutate('stock.scan',{},'Stock checked; expiry quarantine and pending requests updated.');break;
    case 'dispense':modal('Record demo dispensing',`<p>Stock record only. This is not a prescription or treatment recommendation.</p><form>${field('Quantity','quantity',1,'number','min="1" max="10000" required')}${formEnd('Record stock movement')}`,p=>mutate('stock.dispense',{id,...p}));break;
    case 'approve-order':await mutate('order.approve',{id},'Simulated supplier approval recorded.');break;
    case 'receive':modal('Receive an approved new batch',`<p>The expired batch remains quarantined. Replenishment is recorded as a separate batch.</p><form><div class="form-grid">${field('New batch reference','batch','','text','required maxlength="80"')}${field('Expiry date','expiry','','date','required')}</div>${formEnd('Receive batch')}`,p=>mutate('order.receive',{id,...p}));break;
    case 'dispose':modal('Record simulated disposal',`<p>In deployment, only an authorised handler may complete collection and supply disposal evidence. This records a fictional certificate.</p><form>${field('Demonstration certificate reference','certificate','DEMO-CERT-001','text','required maxlength="100"')}${formEnd('Record simulated certificate')}`,p=>mutate('collection.complete',{id,...p}));break;
    case 'tariff':modal('Add or revise an agreement tariff',`<p>Use an existing code, state and agreement to create a new version. Existing claims keep their original snapshot. No official prices are changed.</p><form><div class="form-grid">${field('Service code','code','DEMO-ER','text','required')}${field('Service name','name','Emergency assessment','text','required')}${field('Amount in INR','amount',500,'number','min="0" max="10000000" required')}${field('State / territory','state','Delhi','text','required')}<label class="field full">Participating agreement<input name="scheme" value="Prototype agreement" required></label></div>${formEnd('Save tariff version')}`,p=>mutate('tariff.save',p));break;
    case 'claim':{const ts=state.tariffs.filter(t=>!state.tariffs.some(n=>n.code===t.code&&n.state===t.state&&n.scheme===t.scheme&&n.version>t.version));modal('Create an agreement-based claim',`<p>The amount comes from the selected tariff. This prototype uses fictional agreements, not official government pricing.</p><form><label class="field">Service / package<select name="tariffId">${options(ts.map(t=>[t.id,`${t.name} · ${money(t.amount)} · v${t.version}`]))}</select></label>${formEnd('Submit demo claim')}`,p=>mutate('claim.create',{incidentId:id,...p}));break;}
    case 'approve-claim':await mutate('claim.approve',{id},'Claim approved for simulated settlement.');break;
    case 'settle':await mutate('settlement.run',{},'Weekly settlement batch recorded. No money moved.');break;
    case 'reset':modal('Reset this prototype?',`<p>This deletes all demonstration journeys, requests and settlements in this sandbox. It does not affect any real institution.</p><form>${formEnd('Reset demo data')}`,async()=>{state=await store.reset();subtab='overview';render();toast('Prototype reset.');});break;
    case 'export':{const blob=new Blob([JSON.stringify({prototype:true,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='health-sos-demo-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
    case 'privacy':modal('Your information & this prototype',`<p>Use fictional patients only. This is an interactive prototype, not an emergency service or clinically validated medical device.</p><p><strong>Camera:</strong> off by default. Images are processed in memory. Browser OpenCV runs locally; Python mode sends the selected image to your local server. Optional AI sends it to your configured OpenRouter provider only after explicit consent.</p><p><strong>Location:</strong> requested only when you choose. Coordinates are sent to OpenStreetMap’s Overpass service for nearby listings. Opening maps also shares the selected location with the map provider.</p><p><strong>Records:</strong> ${store.mode()==='sqlite'?'stored in your local SQLite file.':'stored in this browser’s IndexedDB.'} Freely selectable demo workspaces are not production authentication. Administration can reset demo records.</p><p>Hospital bookings, ambulances, police acknowledgements, supplier operations, prices and payments are simulations. No external organisation is contacted by those actions.</p>`);break;
    case 'camera-sample':{const c=document.createElement('canvas');c.width=640;c.height=480;const ctx=c.getContext('2d');ctx.fillStyle='#dfe9d8';ctx.fillRect(0,0,640,480);for(let y=0;y<10;y++)for(let x=0;x<14;x++){ctx.fillStyle=(x+y)%2?'#285e50':'#f1efdf';ctx.fillRect(20+x*42,20+y*40,40,38);}ctx.fillStyle='#fff';ctx.fillRect(50,160,540,150);ctx.fillStyle='#163d3a';ctx.font='bold 28px sans-serif';ctx.fillText('Synthetic camera test image',75,225);ctx.font='18px sans-serif';ctx.fillText('No patient or medical information',75,265);cameraImage=c.toDataURL('image/jpeg',.9);cameraResult=null;scene=null;render();break;}
    case 'camera-browser':{if(!cameraImage)throw Error('Select an image first.');el.disabled=true;el.textContent='Loading OpenCV WebAssembly…';try{cameraResult=await analyzeBrowser(cameraImage);render();toast('Real OpenCV.js processing completed in this browser.');}finally{if(el.isConnected)el.disabled=false;}break;}
    case 'camera-upload':$('#image-file').click();break;
    case 'camera-start':{const stage=$('#camera-stage');stage.innerHTML='<video id="camera-video" autoplay playsinline muted aria-label="Live camera preview"></video>';try{await startCamera($('#camera-video'));$('#camera-actions').innerHTML=btn('Capture frame','camera-capture','','primary')+btn('Stop camera','camera-stop');}catch(e){render();throw e;}break;}
    case 'camera-stop':stopCamera();render();break;
    case 'camera-capture':cameraImage=capture($('#camera-video'));stopCamera();cameraResult=null;scene=null;render();break;
    case 'camera-clear':stopCamera();cameraImage=null;cameraResult=null;scene=null;render();break;
    case 'camera-analyze':{if(!cameraImage)throw Error('Capture or upload an image first.');el.disabled=true;el.textContent='Running OpenCV…';try{if(store.mode()==='sqlite'){try{cameraResult=await store.cameraAnalyze(cameraImage);}catch(error){toast('Local Python engine unavailable. Running OpenCV in your browser instead.');cameraResult=await analyzeBrowser(cameraImage);}}else cameraResult=await analyzeBrowser(cameraImage);render();toast('OpenCV image-quality analysis complete. No clinical assessment made.');}finally{if(el.isConnected){el.disabled=false;el.textContent='Check image with OpenCV';}}break;}
    case 'camera-ai':{if(!cameraImage)throw Error('Capture or upload an image first.');if(!$('#ai-consent')?.checked)throw Error('Confirm permission before sharing the image with the AI provider.');el.disabled=true;try{const response=await store.describeScene(cameraImage);scene=response.description;$('#scene-description').textContent=scene;toast('AI description is unverified. Share observations with a qualified responder.');}finally{el.disabled=false;}break;}
    case 'speak':{if(!('speechSynthesis'in window))throw Error('Speech is unavailable in this browser.');speechSynthesis.cancel();const g=guidance(questions),utterance=new SpeechSynthesisUtterance(g.title+'. '+g.steps.join('. '));utterance.lang='en-IN';utterance.rate=.9;speechSynthesis.speak(utterance);break;}
  }
}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigate(nav.dataset.nav);return;}const el=e.target.closest('[data-do]');if(!el||busy)return;try{busy=true;await doAction(el.dataset.do,el);}catch(error){toast(error.message||'Something went wrong. Please retry.',true);try{state=await store.read();}catch{}}finally{busy=false;}});
document.addEventListener('change',async e=>{
  if(e.target.id==='role'){try{role=e.target.value;await store.setRole(role);state=await store.read();subtab='overview';navigate(role==='patient'?'home':'dashboard');}catch(error){toast(error.message,true);}return;}
  if(e.target.closest('#questions')){questions=Object.fromEntries(new FormData($('#questions')));const g=guidance(questions);$('#guidance-title').textContent=g.title;$('#guidance-steps').innerHTML=g.steps.map(s=>`<li>${esc(s)}</li>`).join('');return;}
  if(e.target.id==='image-file'){try{cameraImage=await readImage(e.target.files[0]);cameraResult=null;scene=null;stopCamera();render();}catch(error){toast(error.message,true);}}
});
document.addEventListener('submit',async e=>{if(e.target.id==='location-form'){e.preventDefault();const p=Object.fromEntries(new FormData(e.target));locationLabel='Coordinates you entered';await searchHospitals(Number(p.lat),Number(p.lon),Number(p.radius));}});
window.addEventListener('pagehide',()=>{stopCamera();if('speechSynthesis'in window)speechSynthesis.cancel();});
try{state=await store.init();const hash=location.hash.slice(1);if(['home','emergency','nearby','journey','guide'].includes(hash))page=hash;render();poll=setInterval(refresh,4000);}catch(error){$('#app').innerHTML=`<main><h1>We couldn’t open your sandbox.</h1><p>${esc(error.message)}</p><p>Allow site storage, or run the SQLite server with <code>npm start</code>.</p><button class="btn" onclick="location.reload()">Try again</button></main>`;}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
